import java.util.ArrayList;
import java.util.List;
import java.util.StringJoiner;

final class Main {

    private Main() {
    }

    public static void bucketSort(float[] values) {
        BucketSorter.sort(values);
    }

    public static void main(String[] args) {
        BucketSortDemo.run();
    }
}

final class BucketSortDemo {

    private static final String SORTED_ARRAY_HEADER = "Sorted array is:";

    private BucketSortDemo() {
    }

    static void run() {
        float[] values = sampleValues();
        BucketSorter.sort(values);

        System.out.println(SORTED_ARRAY_HEADER);
        System.out.println(formatValues(values));
    }

    private static float[] sampleValues() {
        return new float[] {0.897f, 0.565f, 0.656f, 0.1234f, 0.665f, 0.3434f};
    }

    private static String formatValues(float[] values) {
        StringJoiner output = new StringJoiner(" ");
        for (float value : values) {
            output.add(Float.toString(value));
        }
        return output.toString();
    }
}

final class BucketSorter {

    private BucketSorter() {
    }

    static void sort(float[] values) {
        int bucketCount = values.length;
        List<List<Float>> buckets = createBuckets(bucketCount);

        distributeValues(values, buckets);
        sortBuckets(buckets);
        writeBucketsBack(values, buckets);
    }

    private static void insertionSort(List<Float> bucket) {
        for (int i = 1; i < bucket.size(); ++i) {
            float valueToInsert = bucket.get(i);
            int insertionIndex = i - 1;
            while (insertionIndex >= 0 && bucket.get(insertionIndex) > valueToInsert) {
                bucket.set(insertionIndex + 1, bucket.get(insertionIndex));
                insertionIndex--;
            }
            bucket.set(insertionIndex + 1, valueToInsert);
        }
    }

    private static List<List<Float>> createBuckets(int bucketCount) {
        List<List<Float>> buckets = new ArrayList<>(bucketCount);
        for (int i = 0; i < bucketCount; i++) {
            buckets.add(new ArrayList<>());
        }
        return buckets;
    }

    private static void distributeValues(float[] values, List<List<Float>> buckets) {
        int bucketCount = buckets.size();
        for (float value : values) {
            buckets.get(bucketIndex(value, bucketCount)).add(value);
        }
    }

    private static int bucketIndex(float value, int bucketCount) {
        return (int) (bucketCount * value);
    }

    private static void sortBuckets(List<List<Float>> buckets) {
        for (List<Float> bucket : buckets) {
            insertionSort(bucket);
        }
    }

    private static void writeBucketsBack(float[] values, List<List<Float>> buckets) {
        int index = 0;
        for (List<Float> bucket : buckets) {
            for (float value : bucket) {
                values[index++] = value;
            }
        }
    }
}

